// Self-contained local review surface. No CDN, analytics, remote fonts or browser-side model keys.
export const page=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><title>ZESIA · Review consultation</title><link rel="icon" href="/logo.svg"><link rel="stylesheet" href="/style.css"><script src="/app.js" defer></script></head><body><div class="shell"><header><img class="logo" src="/logo.svg" width="40" height="40" alt="ZESIA"><span class="local">Local review</span><button class="icon" id="theme" aria-label="Switch color theme" title="Switch color theme">◐</button></header><main id="conversation" aria-label="Consultation"><div id="notice" role="status" aria-live="polite">Loading your consultation…</div><section id="request" class="message agent" hidden><div class="byline"><span id="requester"></span><span>You / your agent</span></div><h1 id="question"></h1><div id="context"></div><section id="attachments-section" hidden><h2>Attachments <span id="attachment-count"></span></h2><div id="attachments" class="attachments"></div></section><details class="exact"><summary>Full request</summary><pre id="exact"></pre></details></section><section id="response" class="message consultant" hidden><div class="byline"><strong>ZESIA</strong><span id="quality"></span></div><div id="answer"></div></section><div id="error" class="error" role="alert" hidden><span id="error-text"></span><button id="copy-error" class="icon" aria-label="Copy error" title="Copy error"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/></svg></button></div></main><footer><div class="disclosure"><span id="status">Not sent</span><span id="destination"></span><small id="privacy">Only the materials shown here will be sent after you confirm.</small></div><div class="actions"><button id="cancel" class="secondary" disabled>Cancel</button><button id="send" class="primary" disabled>Confirm and send <span aria-hidden="true">↗</span></button></div></footer></div></body></html>`;

export const style=`
:root{color-scheme:light dark;--bg:#fafafa;--panel:#fff;--text:#202124;--muted:#686c73;--line:#e5e6e8;--soft:#f3f4f5;--button:#202124;--on-button:#fff;--error:#9f232b;--focus:#2968db}
@media(prefers-color-scheme:dark){:root{--bg:#111214;--panel:#191a1d;--text:#eeeff1;--muted:#a0a4ac;--line:#303237;--soft:#222428;--button:#eeeff1;--on-button:#191a1d;--error:#ffb5ba}}
:root[data-theme=light]{color-scheme:light;--bg:#fafafa;--panel:#fff;--text:#202124;--muted:#686c73;--line:#e5e6e8;--soft:#f3f4f5;--button:#202124;--on-button:#fff;--error:#9f232b}
:root[data-theme=dark]{color-scheme:dark;--bg:#111214;--panel:#191a1d;--text:#eeeff1;--muted:#a0a4ac;--line:#303237;--soft:#222428;--button:#eeeff1;--on-button:#191a1d;--error:#ffb5ba}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.65 Geist,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button{font:inherit;cursor:pointer}button:disabled{cursor:default;opacity:.5}button:focus-visible,summary:focus-visible{outline:2px solid var(--focus);outline-offset:4px}button{border:0}h1,h2,p,pre{margin:0}h1{font-size:20px;line-height:1.45;font-weight:550;white-space:pre-wrap;overflow-wrap:anywhere}h2{font-size:13px;font-weight:550;margin-bottom:8px}h2 span{color:var(--muted);font-weight:400}.shell{width:min(100%,960px);min-height:100dvh;margin:auto;display:flex;flex-direction:column}header{display:flex;align-items:center;gap:12px;padding:20px 32px}.logo{object-fit:contain}.local{margin-left:auto;color:var(--muted);font-size:12px}.icon{display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;width:32px;height:32px;border-radius:6px;background:transparent;color:var(--muted)}.icon:hover{background:var(--soft);color:var(--text)}main{flex:1;padding:24px 32px 40px;display:flex;flex-direction:column;gap:32px}.message{width:min(100%,720px);overflow-wrap:anywhere}.agent{align-self:flex-end;background:var(--soft);border-radius:18px 18px 4px 18px;padding:24px}.consultant{align-self:flex-start;padding:0 8px}.byline{display:flex;align-items:center;justify-content:space-between;gap:16px;color:var(--muted);font-size:12px;margin-bottom:12px}.byline>span:first-child,.byline strong{font-weight:550;color:var(--text)}#context{margin-top:16px;display:grid;gap:16px}.field h2{text-transform:none}.value{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px}.field details{margin-top:8px}.group{margin-bottom:12px}details summary{cursor:pointer;color:var(--muted);font-size:12px}details[open] summary{margin-bottom:12px}pre{white-space:pre-wrap;word-break:break-word;font-family:inherit;font-size:13px;max-height:400px;overflow:auto}#attachments-section{margin-top:20px}.attachments{display:flex;flex-wrap:wrap;gap:8px}.attachment{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:12px 14px;flex:1 1 200px;min-width:0}.attachment summary{color:var(--text);font-size:13px;overflow-wrap:anywhere}.attachment small{display:block;color:var(--muted);font-size:11px;margin-top:4px}.attachment[open]{flex-basis:100%}.attachment pre{padding-top:4px}.exact{margin-top:20px}.exact pre{font-family:ui-monospace,monospace;font-size:11px}#notice{color:var(--muted);font-size:13px}#notice:empty{display:none}#answer{display:grid;gap:20px}#answer .field h2{color:var(--muted)}.error{display:flex;align-items:flex-start;gap:12px;color:var(--error);font-size:13px;border:1px solid var(--line);border-radius:10px;padding:14px}.error span{flex:1;white-space:pre-wrap;overflow-wrap:anywhere}[hidden]{display:none!important}footer{position:sticky;bottom:0;display:flex;align-items:center;gap:24px;border-top:1px solid var(--line);background:var(--bg);padding:20px 32px}.disclosure{display:flex;flex-wrap:wrap;gap:0 12px;flex:1;min-width:0}.disclosure>span{font-size:12px;overflow-wrap:anywhere}#status{font-weight:550}#destination{color:var(--muted)}.disclosure small{flex-basis:100%;color:var(--muted);font-size:11px;margin-top:4px}.actions{display:flex;gap:8px;flex-shrink:0}.primary,.secondary{height:40px;display:inline-flex;align-items:center;justify-content:center;gap:16px;padding:0 16px;border-radius:8px;font-weight:500;font-size:13px}.primary{background:var(--button);color:var(--on-button)}.primary:not(:disabled):hover{opacity:.87}.secondary{color:var(--muted);background:transparent}.secondary:not(:disabled):hover{background:var(--soft);color:var(--text)}@media(max-width:600px){header{padding:12px 16px}main{padding:16px 16px 28px;gap:24px}.agent{padding:18px;border-radius:14px 14px 4px 14px}h1{font-size:18px}.byline{gap:8px;flex-wrap:wrap}.byline>span:last-child{font-size:11px}footer{padding:16px;flex-wrap:wrap;gap:12px}.disclosure{flex-basis:100%}.actions{margin-left:auto}.attachment{flex-basis:100%}}`;

export const client=`'use strict';
const $=id=>document.getElementById(id);let key=new URLSearchParams(location.hash.slice(1)).get('key');
if(key){sessionStorage.setItem('zesia-review-key',key);history.replaceState(null,'',location.pathname);}else key=sessionStorage.getItem('zesia-review-key');
let current,working=false,stopped=false,attempted=false,lastResult='',lastStatus='';
const labels={prepared:'Not sent',preflight:'Checking request',unknown:'Outcome unknown',completed:'Consultation returned',failed:'Not sent · preflight failed',cancelled:'Cancelled'};
const human=key=>key.replace(/([a-z])([A-Z])/g,'$1 $2').replace(/_/g,' ').replace(/^./,s=>s.toUpperCase());
function text(value){return typeof value==='string'?value:JSON.stringify(value,null,2);}
function field(parent,name,value){if(value===undefined||value===null||value===''||(Array.isArray(value)&&!value.length))return;const section=document.createElement('section');section.className='field';const h=document.createElement('h2');h.textContent=name;const content=document.createElement('div');content.className='value';content.textContent=text(value);section.append(h,content);parent.append(section);}
function objectFields(parent,object){for(const [key,value]of Object.entries(object||{})){if(Array.isArray(value)){if(value.length){const section=document.createElement('section');section.className='field';const h=document.createElement('h2');h.textContent=human(key);section.append(h);for(const item of value){const group=document.createElement('div');group.className='group';if(item&&typeof item==='object')objectFields(group,item);else field(group,'',item);section.append(group);}parent.append(section);}}else if(value&&typeof value==='object'){const group=document.createElement('section');const h=document.createElement('h2');h.textContent=human(key);group.append(h);objectFields(group,value);parent.append(group);}else field(parent,human(key),value);}}
function requestContext(context){const parent=$('context');parent.replaceChildren();for(const [name,value]of Object.entries(context||{})){
 if(name==='materials')continue;
 if(name==='statements'&&Array.isArray(value)){for(const statement of value){const section=document.createElement('section');section.className='field';const origin={user_statement:'User statement',observation:'Agent observation',agent_inference:'Agent inference'}[statement.origin]||human(statement.origin||'Statement');field(section,origin+' · '+human(statement.kind||'fact'),statement.text);const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Source';details.append(summary);field(details,'Reference',statement.sourceRef||'Unavailable');if(statement.sourceQuote)field(details,'Original quote',statement.sourceQuote);section.append(details);parent.append(section);}continue;}
 if(name==='originalReply'){const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Original agent response';details.append(summary);field(details,'',value);parent.append(details);continue;}
 objectFields(parent,{[name]:value});
}}
function showError(message){$('error').hidden=false;$('error-text').textContent=message;}
async function api(path,body){const response=await fetch(path,{cache:'no-store',headers:{Authorization:'Bearer '+key,...(body?{'Content-Type':'application/json'}:{})},...(body?{method:'POST',body:JSON.stringify(body)}:{})});const value=await response.json();if(!response.ok)throw Error(value.message||'The local session could not be read.');return value;}
function render(view){current=view;const packet=view.packet;$('request').hidden=false;$('question').textContent=packet.brief;$('requester').textContent=packet.requester;$('destination').textContent=view.destination;$('exact').textContent=JSON.stringify(packet,null,2);
if(!lastStatus){requestContext(packet.context);const attachments=packet.context?.materials||[];$('attachment-count').textContent=String(attachments.length);$('attachments-section').hidden=!attachments.length;for(const material of attachments){const item=document.createElement('details');item.className='attachment';const summary=document.createElement('summary');summary.textContent=material.id||'Attachment';const size=document.createElement('small');size.textContent=new TextEncoder().encode(material.content||'').length.toLocaleString()+' bytes · prepared excerpt';const pre=document.createElement('pre');pre.textContent=material.content||'';item.append(summary,size,pre);for(const [name,value]of Object.entries(material)){if(!['id','content'].includes(name))field(item,human(name),value);}$('attachments').append(item);}}
const expired=Date.now()>Date.parse(view.expiresAt),pending=working||view.requestInProgress;
$('status').textContent=pending?'Request in progress':expired&&view.status==='prepared'?'Review expired':labels[view.status]||view.status;
$('notice').textContent=pending?'Waiting for ZESIA. This is a single request; closing this tab will not resend it.':view.status==='prepared'?'Review the selected materials. Nothing has been sent.':'';
$('send').disabled=stopped||attempted||pending||expired||view.status!=='prepared';$('cancel').disabled=stopped||attempted||pending||expired||view.status!=='prepared';
if(view.result && JSON.stringify(view.result)!==lastResult){lastResult=JSON.stringify(view.result);const result=view.result;if(result.ok){$('response').hidden=false;$('quality').textContent=result.qualityStatus?human(result.qualityStatus):'External advice';$('answer').replaceChildren();if(result.decision)objectFields($('answer'),result.decision);else field($('answer'),'Assessment',result.advice);if(result.expertMatch)objectFields($('answer'),{expertMatch:result.expertMatch});if(result.review)objectFields($('answer'),{review:result.review});if(result.followUp?.requests?.length){objectFields($('answer'),{questions:result.followUp.requests});field($('answer'),'Continue with your agent','Return to your agent to gather the requested evidence or answer a decision. Each follow-up requires a new review.');}if(result.usage)objectFields($('answer'),{usage:result.usage});$('privacy').textContent='The result is saved locally for your agent. Advice still needs its assessment.';}else if(view.status!=='cancelled'){showError((result.message||result.code||'The consultation did not return a result.')+(result.outcome==='unknown'?' The outcome is unknown. Do not resend.':''));}}lastStatus=view.status;}
async function refresh(){if(stopped)return;try{render(await api('/api/view'));}catch(error){showError(error.message+' Reopen the review from your agent if this session expired.');$('send').disabled=true;$('cancel').disabled=true;stopped=true;}if(!stopped)setTimeout(refresh,1500);}
async function act(action){if(working||!current)return;working=true;attempted=true;render(current);try{const result=await api('/api/'+action,{approvedHash:current.approvedHash});current.result=result;current.status=result.status||(!result.ok?(result.outcome==='unknown'?'unknown':'failed'):'completed');}catch(error){showError(error.message+' Check the local result; do not submit again.');stopped=true;}finally{working=false;if(!stopped)render(current);else{$('send').disabled=true;$('cancel').disabled=true;}}}
$('send').addEventListener('click',()=>act('send'));$('cancel').addEventListener('click',()=>act('cancel'));
$('copy-error').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('error-text').textContent);$('copy-error').setAttribute('aria-label','Copied');$('copy-error').title='Copied';setTimeout(()=>{$('copy-error').setAttribute('aria-label','Copy error');$('copy-error').title='Copy error';},1500);}catch{$('copy-error').title='Select and copy the error text.';}});
$('theme').addEventListener('click',()=>{const root=document.documentElement;const dark=root.dataset.theme?root.dataset.theme==='dark':matchMedia('(prefers-color-scheme:dark)').matches;root.dataset.theme=dark?'light':'dark';});
if(!key){showError('This review link is missing its local access key. Open the full link from your agent.');$('notice').textContent='';}else refresh();
`;

// Existing ZESIA mark from the public DSH adapter; original artwork unchanged.
export const logo="<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 64 64\" width=\"64\" height=\"64\"><image x=\"2\" y=\"8.25\" width=\"60\" height=\"47.5\" preserveAspectRatio=\"none\" href=\"data:image/png;base64,\"/></svg>\n";
